The `useSensors.ts` hook is the **heartbeat of the FoodCompass app**. It combines three distinct hardware subsystems into a unified, reactive state:

1. **Magnetometer / Compass**: Tells which way the phone is physically pointing.
2. **GPS Geolocation**: Tracks where the user is walking in real-time.
3. **Haptic Engine**: Gives subtle vibrations so the user doesn't have to keep staring at the screen.

Here is the complete, production-ready implementation, followed by a step-by-step breakdown of how each part works (including the notorious iOS vs. Android compass differences).

---

### 1. Complete Code: `src/hooks/useSensors.ts`

```typescript
import { useState, useEffect, useRef, useCallback } from 'react';
import { Geolocation, Position } from '@capacitor/geolocation';
import { Haptics, ImpactStyle, NotificationType } from '@capacitor/haptics';

export interface Coordinates {
  lat: number;
  lng: number;
}

export interface SensorState {
  userLocation: Coordinates | null;
  heading: number; // 0° to 360° (0 = True/Magnetic North)
  accuracy: number | null; // meters
  permissionGranted: boolean;
  error: string | null;
}

export function useSensors(targetLocation?: Coordinates | null) {
  const [sensorState, setSensorState] = useState<SensorState>({
    userLocation: null,
    heading: 0,
    accuracy: null,
    permissionGranted: false,
    error: null,
  });

  // Track previous heading alignment to avoid spamming vibrations
  const wasFacingTargetRef = useRef(false);
  const hasArrivedRef = useRef(false);

  // -------------------------------------------------------------
  // 1. COMPASS / DEVICE ORIENTATION
  // -------------------------------------------------------------
  const handleOrientation = useCallback((event: DeviceOrientationEvent) => {
    let compassHeading = 0;

    // iOS Safari / WebKit provides direct 0-360 compass heading
    if ('webkitCompassHeading' in event && typeof (event as any).webkitCompassHeading === 'number') {
      compassHeading = (event as any).webkitCompassHeading;

