3: // Generates an elegant two-tone arrival chime with zero network assets
4: export function playArrivalChime() {
5:     try {
6:         const AudioContext = window.AudioContext || (window as any).webkitAudioContext;
7:         if (!AudioContext) return;
8:         const ctx = new AudioContext();
9: 
10:         const playTone = (freq: number, start: number, duration: number) => {
11:             const osc = ctx.createOscillator();
12:             const gain = ctx.createGain();
13:             osc.type = 'sine';
14:             osc.frequency.setValueAtTime(freq, ctx.currentTime + start);
15: 
16:             gain.gain.setValueAtTime(0, ctx.currentTime + start);
17:             gain.gain.linearRampToValueAtTime(0.3, ctx.currentTime + start + 0.05);
18:             gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + start + duration);
19: 
20:             osc.connect(gain);
21:             gain.connect(ctx.destination);
22:             osc.start(ctx.currentTime + start);
23:             osc.stop(ctx.currentTime + start + duration);
24:         };
25: 
26:         // Two-tone rising chord (E5 -> B5)
27:         playTone(659.25, 0, 0.4);
28:         playTone(987.77, 0.25, 0.6);
29:     } catch (err) {
30:         console.error('Audio playback error:', err);
31:     }
32: }
33: 
34: // Optional: Short hands-free voice notification
35: export function speakArrival(restaurantName: string, dish: string) {
36:     if ('speechSynthesis' in window) {
37:         const utterance = new SpeechSynthesisUtterance(
38:             `You have arrived at ${restaurantName}. Look for the ${dish}.`
39:         );
40:         utterance.rate = 1.0;
41:         utterance.pitch = 1.1;
42:         window.speechSynthesis.speak(utterance);
43:     }
